 26→/// Executes queries directly against a database via ADBC.
 27→///
 28→/// `AdbcConnection` is not `Send`/`Sync` (the underlying `ManagedConnection`
 29→/// uses raw FFI pointers), so we wrap it in `Arc<Mutex<>>` to satisfy the
 30→/// `Send + Sync` bounds required by [`QueryExecutor`] and to allow cloning
 31→/// the executor across concurrent tasks.
 32→pub(crate) struct AdbcDirectQueryExecutor {
 33→    conn: Arc<Mutex<AdbcConnection>>,
 34→}
 35→
 36→impl AdbcDirectQueryExecutor {
 37→    pub(crate) fn new(conn: AdbcConnection) -> Self {
 38→        Self {
 39→            conn: Arc::new(Mutex::new(conn)),
 40→        }
 41→    }
 42→
 43→    pub(crate) fn from_shared(conn: Arc<Mutex<AdbcConnection>>) -> Self {
 44→        Self { conn }
 45→    }
 46→}
 47→
 48→impl Clone for AdbcDirectQueryExecutor {
 49→    fn clone(&self) -> Self {
 50→        Self {
 51→            conn: Arc::clone(&self.conn),
 52→        }
 53→    }
 54→}
