 56→#[async_trait::async_trait]
 57→impl QueryExecutor for AdbcDirectQueryExecutor {
 58→    async fn execute(
 59→        &self,
 60→        query: &test_framework::queries::Query,
 61→    ) -> anyhow::Result<ExecutionResult> {
 62→        let sql = query.to_sql_with_inlined_params().to_string();
 63→        let conn = Arc::clone(&self.conn);
 64→
 65→        // `AdbcConnection::query()` is synchronous (ADBC has no async API),
 66→        // so we run it on the blocking thread pool to avoid stalling the tokio runtime.
 67→        let (duration, batches) = tokio::task::spawn_blocking(move || {
 68→            let start = std::time::Instant::now();
 69→            let mut guard = conn
 70→                .lock()
 71→                .map_err(|e| anyhow::anyhow!("Lock poisoned: {e}"))?;
 72→            let batches = guard.query(&sql).map_err(|e| anyhow::anyhow!("{e}"))?;
 73→            Ok::<_, anyhow::Error>((start.elapsed(), batches))
 74→        })
 75→        .await??;
 76→
 77→        let row_count: usize = batches
 78→            .iter()
 79→            .map(arrow::array::RecordBatch::num_rows)
 80→            .sum();
 81→
 82→        Ok(ExecutionResult {
 83→            duration,
 84→            row_count,
 85→            batches: Some(batches),
 86→        })
 87→    }
