 45→/// Record the latest SUT metrics snapshot as OTel gauge values.
 46→fn record_sut_metrics(response: &MetricsResponse, attributes: &[KeyValue]) {
 47→    // Resource metrics
 48→    if let Some(cpu) = response.resource.cpu_usage_percent {
 49→        crate::metrics::SUT_CPU_USAGE_PERCENT.record(cpu, attributes);
 50→    }
 51→    if let Some(mem) = response.resource.memory_usage_bytes {
 52→        crate::metrics::SUT_MEMORY_USAGE_BYTES.record(mem, attributes);
 53→    }
 54→    if let Some(v) = response.resource.disk_read_bytes {
 55→        crate::metrics::SUT_DISK_READ_BYTES.record(v, attributes);
 56→    }
 57→    if let Some(v) = response.resource.disk_write_bytes {
 58→        crate::metrics::SUT_DISK_WRITE_BYTES.record(v, attributes);
 59→    }
 60→    if let Some(v) = response.resource.disk_read_iops {
 61→        crate::metrics::SUT_DISK_READ_IOPS.record(v, attributes);
 62→    }
 63→    if let Some(v) = response.resource.disk_write_iops {
 64→        crate::metrics::SUT_DISK_WRITE_IOPS.record(v, attributes);
 65→    }
 66→
 67→    // Ingestion metrics
 68→    if let Some(v) = response.ingestion.rows_ingested {
 69→        crate::metrics::INGESTION_ROWS_TOTAL.record(v, attributes);
 70→    }
 71→    if let Some(v) = response.ingestion.bytes_ingested {
 72→        crate::metrics::INGESTION_BYTES_TOTAL.record(v, attributes);
 73→    }
 74→    if let Some(v) = response.ingestion.rows_per_sec {
 75→        crate::metrics::INGESTION_ROWS_PER_SEC.record(v, attributes);
 76→    }
 77→    if let Some(v) = response.ingestion.active_connections {
 78→        crate::metrics::ACTIVE_CONNECTIONS.record(v, attributes);
 79→    }
 80→}
