 82→/// Spawn a task that periodically scrapes SUT metrics from the system adapter.
 83→///
 84→/// Returns a `JoinHandle` that resolves to the last `MetricsResponse` received
 85→/// (or `None` if no successful scrape occurred).
 86→fn spawn_sut_metrics_scraper(
 87→    adapter: Arc<Mutex<system_adapter_protocol::Client>>,
 88→    run_id: uuid::Uuid,
 89→    token: CancellationToken,
 90→    interval: Duration,
 91→    attributes: Vec<KeyValue>,
 92→) -> tokio::task::JoinHandle<Option<MetricsResponse>> {
 93→    tokio::spawn(async move {
 94→        let mut last_response: Option<MetricsResponse> = None;
 95→        let mut ticker = tokio::time::interval(interval);
 96→        loop {
 97→            tokio::select! {
 98→                _ = ticker.tick() => {
 99→                    match adapter.lock().await.metrics(run_id).await {
100→                        Ok(resp) => {
101→                            record_sut_metrics(&resp, &attributes);
102→                            last_response = Some(resp);
103→                        }
104→                        Err(e) => {
105→                            eprintln!("SUT metrics scrape failed: {e}");
106→                        }
107→                    }
108→                }
109→                () = token.cancelled() => {
110→                    // Final scrape before exiting
111→                    if let Ok(resp) = adapter.lock().await.metrics(run_id).await {
112→                        record_sut_metrics(&resp, &attributes);
113→                        last_response = Some(resp);
114→                    }
115→                    break;
116→                }
117→            }
118→        }
119→        last_response
120→    })
121→}
