198→#[expect(clippy::too_many_lines)]
199→pub(crate) async fn run(
200→    scenario: &Scenario,
201→    common_args: &CommonArgs,
202→    adbc_conn: adbc_client::AdbcConnection,
203→    etl_pipeline: &mut ETLPipeline,
204→    checkpoint_steps: Option<usize>,
205→) -> anyhow::Result<()> {
206→    let metric_attributes = run_metric_attributes(common_args);
207→
208→    scenario.load_query_set()?;
209→
210→    let load_resource = Resource::builder_empty()
211→        .with_attributes(vec![
212→            KeyValue::new("service.name", "spicebench"),
213→            KeyValue::new("type", "spicebench"),
214→            KeyValue::new("adapter_name", common_args.system_adapter_name.clone()),
215→            KeyValue::new("scenario", scenario.to_string()),
216→        ])
217→        .build();
218→
219→    // Create telemetry with resource upfront, before any metrics calls
220→    let telemetry = super::create_telemetry_with_resource(common_args, load_resource);
221→
222→    // Create the appropriate query executor based on args, sharing the ADBC connection
223→    // so the freshness scraper can also query through it.
224→    let shared_conn = Arc::new(std::sync::Mutex::new(adbc_conn));
225→    let executor = Box::new(adbc_executor::AdbcDirectQueryExecutor::from_shared(
226→        Arc::clone(&shared_conn),
227→    ));
228→
229→    println!("Running benchmark");
230→
231→    let load_end_condition = scenario.end_condition();
232→
233→    // Create streaming OTLP exporter if OTLP endpoint is configured
234→    let streaming_exporter = common_args
235→        .otlp_endpoint
236→        .as_ref()
237→        .map(|endpoint| StreamingOtlpExporter::spawn(endpoint.clone()));
238→
239→    // Spawn SUT metrics scraper if --scrape-sut-metrics is enabled and a system adapter is configured
240→    let sut_scraper_token = CancellationToken::new();
241→    let sut_scraper_handle = if common_args.scrape_sut_metrics
242→        && (common_args.system_adapter_stdio_cmd.is_some()
243→            || common_args.system_adapter_http_url.is_some())
244→    {
245→        let adapter = super::connect_system_adapter(common_args).await?;
246→        let run_id = uuid::Uuid::new_v4();
247→        println!("SUT metrics scraping enabled (run_id={run_id})");
248→        Some(spawn_sut_metrics_scraper(
249→            Arc::new(Mutex::new(adapter)),
250→            run_id,
251→            sut_scraper_token.clone(),
252→            Duration::from_secs(5),
253→            metric_attributes.clone(),
254→        ))
255→    } else {
256→        None
257→    };
258→
259→    // Spawn e2e checker
260→    let table_names: Vec<String> = etl_pipeline.dataset().tables().keys().cloned().collect();
261→    let e2e_latency_token = CancellationToken::new();
262→    let e2e_latency_handle = spawn_e2e_latency_check(
263→        Arc::clone(&shared_conn),
264→        table_names,
265→        e2e_latency_token.clone(),
266→        Duration::from_secs(5),
267→    );
268→
269→    // Record client concurrency as a gauge
270→    crate::metrics::ACTIVE_CONNECTIONS.record(
271→        common_args.concurrency.try_into().unwrap_or(0),
272→        &metric_attributes,
273→    );
274→
275→    let mut test_builder = NotStarted::new()
276→        .with_parallel_count(common_args.concurrency)
277→        .with_end_condition(load_end_condition)
278→        .with_query_executor(executor);
279→
280→    // Add streaming metrics sender if exporter is configured
281→    if let Some(exporter) = &streaming_exporter {
282→        test_builder = test_builder.with_streaming_metrics(exporter.sender());
283→    }
284→
285→    let (query_set, test_builder) =
286→        super::build_test_with_validation(scenario, test_builder).await?;
287→
288→    let _queries = query_set.get_queries(None, None, None).await?;
289→
290→    let throughput_test = SpiceTest::<NotStarted>::new(scenario.to_string(), test_builder)
291→        .with_progress_bars(false)
292→        .start()?;
293→    let shutdown_token = throughput_test.cancellation_token();
294→
295→    // --- Start the ETL pipeline (remaining batches) ---
296→    // If checkpoint_steps is set, use `.run(steps)` so the pipeline pauses
297→    // at checkpoint boundaries. Otherwise fall back to `.start()` which runs
298→    // all remaining batches without pausing.
299→    tracing::info!("Starting ETL pipeline (remaining batches)...");
300→    let mut etl_state_rx = etl_pipeline.state_watch();
301→    if let Some(steps) = checkpoint_steps {
302→        tracing::info!(checkpoint_steps = steps, "Using checkpoint-aware ETL mode");
303→        etl_pipeline.run(steps).await?;
304→    } else {
305→        etl_pipeline.start().await?;
306→    }
307→
308→    let test_future = throughput_test.wait();
309→    tokio::pin!(test_future);
310→
311→    // Wait for ETL pipeline state changes, handling both pauses (checkpoint
312→    // boundaries) and stops (completion / error / cancellation).
313→    //
314→    // When the pipeline pauses at a checkpoint boundary we immediately
315→    // continue it. TODO: In the future this is where checkpoint-based query result
316→    // validation would be triggered before resuming.
317→    //
318→    // If interrupted (ctrl-c), cancel both the test and the ETL pipeline.
319→    let etl_error: Option<String> = loop {
320→        tokio::select! {
321→            // ETL state changed — check if stopped or paused
322→            _ = etl_state_rx.changed() => {
323→                let state = etl_state_rx.borrow_and_update().clone();
324→                match state {
325→                    PipelineState::Paused => {
326→                        tracing::info!("ETL pipeline paused at checkpoint boundary");
327→                        // TODO: run checkpoint-based query result validation here
328→                        if let Err(e) = etl_pipeline.continue_pipeline() {
329→                            eprintln!("Failed to continue ETL pipeline after pause: {e}");
330→                            shutdown_token.cancel();
331→                            break Some(format!("Failed to continue ETL pipeline: {e}"));
332→                        }
333→                        tracing::info!("ETL pipeline resumed");
334→                    }
335→                    PipelineState::Stopped(StopReason::Completed) => {
336→                        println!("ETL pipeline completed, stopping benchmark...");
337→                        shutdown_token.cancel();
338→                        break None;
339→                    }
340→                    PipelineState::Stopped(StopReason::Error(ref e)) => {
341→                        eprintln!("ETL pipeline failed: {e}");
342→                        shutdown_token.cancel();
343→                        break Some(e.clone());
344→                    }
345→                    PipelineState::Stopped(StopReason::Cancelled) => {
346→                        println!("ETL pipeline was cancelled, stopping benchmark...");
347→                        shutdown_token.cancel();
348→                        break None;
349→                    }
350→                    _ => { /* still running, keep waiting */ }
351→                }
352→            }
353→            // ctrl-c: stop everything
354→            _ = signal::ctrl_c() => {
355→                println!("Interrupt received, stopping benchmark...");
356→                shutdown_token.cancel();
357→                etl_pipeline.cancel();
358→                break None;
359→            }
360→        }
361→    };
362→
363→    let test = match test_future.await {
364→        Ok(test) => test,
365→        Err(e) => {
366→            return Err(e);
367→        }
368→    };
369→
370→    // Propagate ETL error after collecting the test result
371→    if let Some(etl_err) = etl_error {
372→        return Err(anyhow::anyhow!("ETL pipeline failed: {etl_err}"));
373→    }
374→    test.get_query_durations().statistical_set()?;
375→
376→    // Get all query durations for overall statistics before ending the test
377→    let all_durations = test.get_query_durations().clone();
378→    let all_duration_values: Vec<_> = all_durations.values().flatten().copied().collect();
379→
380→    let metrics: QueryMetrics<_, NoExtendedMetrics> = test.collect(TestType::Load)?;
381→    let _ = test.end();
382→
383→    // Record per-query metrics for load test
384→    for query in &metrics.metrics {
385→        let query_name = &query.query_name;
386→        let mut attributes = metric_attributes.clone();
387→        attributes.push(KeyValue::new("query_name", query_name.to_string()));
388→
389→        let status: u64 = u64::from(match &query.query_status {
390→            QueryStatus::Passed => true,
391→            QueryStatus::Failed(_) => false,
392→        });
393→
394→        crate::metrics::QUERY_STATUS.record(status, &attributes);
395→        crate::metrics::MEDIAN_DURATION.record(query.median_duration_ms, &attributes);
396→        crate::metrics::MIN_DURATION.record(query.min_duration_ms, &attributes);
397→        crate::metrics::MAX_DURATION.record(query.max_duration_ms, &attributes);
398→        crate::metrics::ITERATIONS.record(query.iterations.try_into()?, &attributes);
399→        crate::metrics::P99_DURATION.record(query.percentile_99_duration_ms, &attributes);
400→    }
401→
402→    // Calculate and record overall load test P99
403→    if !all_duration_values.is_empty() {
404→        let overall_p99 = all_duration_values.percentile(99.0)?;
405→        crate::metrics::P99_DURATION
406→            .record(overall_p99.as_millis().try_into()?, &metric_attributes);
407→    }
408→    crate::metrics::TEST_DURATION.record(
409→        (metrics.finished_at - metrics.started_at).try_into()?,
410→        &metric_attributes,
411→    );
412→
413→    // Query throughput metrics
414→    let total_iterations: u64 = metrics.metrics.iter().map(|q| q.iterations as u64).sum();
415→    let test_duration_secs = (metrics.finished_at - metrics.started_at) as f64 / 1000.0;
416→    crate::metrics::QUERIES_TOTAL.add(total_iterations, &metric_attributes);
417→    if test_duration_secs > 0.0 {
418→        let qps = total_iterations as f64 / test_duration_secs;
419→        crate::metrics::QUERIES_PER_SEC.record(qps, &metric_attributes);
420→
421→        // Efficiency: queries/s normalized by CPU core count
422→        let cpu_cores = std::thread::available_parallelism()
423→            .map(|n| n.get() as f64)
424→            .unwrap_or(1.0);
425→        if cpu_cores > 0.0 {
426→            crate::metrics::EFFICIENCY_QUERIES_PER_CORE.record(qps / cpu_cores, &metric_attributes);
427→        }
428→    }
429→
430→    // Stop SUT metrics scraper
431→    sut_scraper_token.cancel();
432→    if let Some(handle) = sut_scraper_handle
433→        && let Ok(Some(last_sut_metrics)) = handle.await
434→    {
435→        println!(
436→            "Final SUT metrics: cpu={:?}%, mem={:?}B, ingested_rows={:?}, ingested_bytes={:?}",
437→            last_sut_metrics.resource.cpu_usage_percent,
438→            last_sut_metrics.resource.memory_usage_bytes,
439→            last_sut_metrics.ingestion.rows_ingested,
440→            last_sut_metrics.ingestion.bytes_ingested,
441→        );
442→    }
443→
444→    // Stop freshness scraper and emit P99 metrics
445→    e2e_latency_token.cancel();
446→    if let Ok(samples_by_table) = e2e_latency_handle.await {
447→        let mut all_samples: Vec<f64> = Vec::new();
448→        for (table_name, samples) in &samples_by_table {
449→            if !samples.is_empty() {
450→                all_samples.extend(samples);
451→                let mut sorted = samples.clone();
452→                sorted.sort_by(|a, b| a.partial_cmp(b).unwrap());
453→                let idx = ((sorted.len() as f64 * 0.99) as usize).min(sorted.len() - 1);
454→                let p99 = sorted[idx];
455→                let attrs = vec![KeyValue::new("table_name", table_name.clone())];
456→                crate::metrics::E2E_LATENCY_P99_MS.record(p99, &attrs);
457→            }
458→        }
459→        if !all_samples.is_empty() {
460→            all_samples.sort_by(|a, b| a.partial_cmp(b).unwrap());
461→            let idx = ((all_samples.len() as f64 * 0.99) as usize).min(all_samples.len() - 1);
462→            let p99 = all_samples[idx];
463→            crate::metrics::E2E_LATENCY_P99_MS.record(p99, &[KeyValue::new("table_name", "")]);
464→            println!(
465→                "Data freshness P99: {p99:.1}ms ({} samples)",
466→                all_samples.len()
467→            );
468→        }
469→    }
470→
471→    println!("{}", vec!["-"; 30].join(""));
472→    println!("Benchmark metrics:");
473→    let records = metrics.build_records()?;
474→    print_batches(&records)?;
475→
476→    // Shutdown streaming exporter before emitting final telemetry
477→    if let Some(exporter) = streaming_exporter {
478→        exporter.shutdown().await;
479→    }
480→
481→    println!("Benchmark completed");
482→
483→    telemetry.emit().await?;
484→
485→    Ok(())
486→}
