 42→fn create_tables_request_datasets(
 43→    dataset: &Arc<dyn Dataset>,
 44→) -> HashMap<String, system_adapter_protocol::DatasetConfig> {
 45→    dataset
 46→        .tables()
 47→        .into_iter()
 48→        .map(|(name, table)| {
 49→            let mut fields: Vec<_> = table.schema.fields().iter().cloned().collect();
 50→            fields.push(Arc::new(Field::new(
 51→                "__created_at",
 52→                DataType::Timestamp(TimeUnit::Microsecond, Some("UTC".into())),
 53→                true,
 54→            )));
 55→
 56→            (
 57→                name,
 58→                system_adapter_protocol::DatasetConfig {
 59→                    schema: Arc::new(Schema::new(fields)),
 60→                },
 61→            )
 62→        })
 63→        .collect()
 64→}
