 79→#[tokio::main]
 80→async fn main() -> anyhow::Result<()> {
 81→    let _ = rustls::crypto::CryptoProvider::install_default(
 82→        rustls::crypto::aws_lc_rs::default_provider(),
 83→    );
 84→
 85→    tracing_subscriber::fmt()
 86→        .with_max_level(Level::INFO)
 87→        .with_env_filter(EnvFilter::from_default_env())
 88→        .init();
 89→
 90→    let cli = Cli::parse();
 91→
 92→    // --- Construct the ETL pipeline ---
 93→    let dataset_source = match &cli.common.scenario {
 94→        Scenario::TPCH => DatasetSource::Tpch,
 95→    };
 96→
 97→    let generation_config = GenerationDatasetConfig {
 98→        dataset_type: match &dataset_source {
 99→            DatasetSource::Tpch => "tpch".to_string(),
100→            DatasetSource::SimpleSequence => "simple_sequence".to_string(),
101→        },
102→        scale_factor: cli.common.scale_factor,
103→        num_steps: cli.common.etl_num_steps,
104→    };
105→
106→    let source_config = TargetConfig {
107→        bucket: cli.common.etl_bucket.clone(),
108→        prefix: cli.common.etl_source_prefix.clone(),
109→        region: cli.common.etl_region.clone(),
110→        endpoint: cli.common.etl_endpoint.clone(),
111→    };
112→
113→    let source = Arc::new(S3Storage::new(&source_config)?);
114→
115→    // --- Connect to the system adapter ---
116→    let mut system_adapter_client = match connect_system_adapter(&cli.common).await {
117→        Ok(system_adapter_client) => system_adapter_client,
118→        Err(e) => {
119→            return Err(anyhow::anyhow!("Failed to connect to system adapter: {e}"));
120→        }
121→    };
122→
123→    let run_id = uuid::Uuid::new_v4();
124→    let mutations = MutationConfig::new(0.1, 0.1);
125→
126→    let setup_dataset = dataset_source.create(
127→        &generation_config,
128→        &mutations,
129→        Arc::clone(&source) as Arc<dyn DataStorage>,
130→    )?;
131→    let datasets = create_tables_request_datasets(&setup_dataset);
132→
133→    let setup_metadata = std::collections::HashMap::from([
134→        (
135→            "executor_instance_type".to_string(),
136→            serde_json::Value::String(cli.common.executor_instance_type.clone()),
137→        ),
138→        (
139→            "table_format".to_string(),
140→            serde_json::Value::String(cli.common.table_format.to_string()),
141→        ),
142→    ]);
143→
144→    let adbc_driver = match system_adapter_client.setup(run_id, setup_metadata).await {
145→        Ok(response) => response,
146→        Err(e) => {
147→            return Err(anyhow::anyhow!("Failed to setup system adapter: {e}"));
148→        }
149→    };
150→
151→    // After successful setup, always teardown even if there are errors in between.
152→    let result = run_benchmark(
153→        &cli.common,
154→        &mut system_adapter_client,
155→        run_id,
156→        adbc_driver,
157→        dataset_source,
158→        &generation_config,
159→        &mutations,
160→        source,
161→        datasets,
162→    )
163→    .await;
164→
165→    if let Err(e) = system_adapter_client.teardown(run_id).await {
166→        tracing::error!("Failed to teardown system adapter: {e}");
167→    }
168→
169→    result
170→}
