 17→//! JSON-RPC protocol definitions for system adapter communication.
 18→//!
 19→//! This crate defines the request/response types for the system adapter
 20→//! JSON-RPC protocol, which allows spicebench to communicate with external
 21→//! benchmark execution environments.
 22→//!
 23→//! # Features
 24→//!
 25→//! - **Protocol types**: Request/response types for setup, create_tables, teardown, and metrics
 26→//! - **Client**: Ready-to-use client with Stdio and HTTP transports (requires `client` feature)
 27→//! - **Server**: Easy server implementation via Handler trait (requires `server` feature)
 28→//! - **JSON-RPC**: Standard JSON-RPC 2.0 envelope types
 29→//!
 30→//! # Client Example
 31→//!
 32→//! ```no_run
 33→//! # #[cfg(feature = "client")]
 34→//! # async fn example() -> Result<(), Box<dyn std::error::Error>> {
 35→//! use system_adapter_protocol::Client;
 36→//! use std::collections::HashMap;
 37→//! use uuid::Uuid;
 38→//!
 39→//! // Create an HTTP client
 40→//! let mut client = Client::http("http://localhost:8080");
 41→//!
 42→//! // Setup a benchmark run
 43→//! let run_id = Uuid::new_v4();
 44→//! let setup_response = client.setup(run_id, HashMap::new()).await?;
 45→//! let create_tables_response = client.create_tables(run_id, HashMap::new()).await?;
 46→//!
 47→//! println!("Driver: {:?}", setup_response.driver);
 48→//!
 49→//! // Teardown the run
 50→//! let teardown_response = client.teardown(run_id).await?;
 51→//! # Ok(())
 52→//! # }
 53→//! ```
 54→//!
 55→//! # Server Example
 56→//!
 57→//! ```no_run
 58→//! # #[cfg(feature = "server")]
 59→//! # async fn example() -> Result<(), Box<dyn std::error::Error>> {
 60→//! use system_adapter_protocol::{
 61→//!     AdbcDriver, CreateTablesResponse, DatasetConfig, Handler, Server, SetupResponse,
 62→//!     TeardownResponse,
 63→//! };
 64→//! use async_trait::async_trait;
 65→//! use std::collections::HashMap;
 66→//! use uuid::Uuid;
 67→//!
 68→//! struct MyHandler;
 69→//!
 70→//! #[async_trait]
 71→//! impl Handler for MyHandler {
 72→//!     async fn setup(
 73→//!         &mut self,
 74→//!         run_id: Uuid,
 75→//!         metadata: HashMap<String, serde_json::Value>,
 76→//!     ) -> Result<SetupResponse, String> {
 77→//!         // Your setup logic here
 78→//!         let _ = metadata;
 79→//!         Ok(SetupResponse {
 80→//!             driver: AdbcDriver::Flightsql,
 81→//!             db_kwargs: HashMap::new(),
 82→//!         })
 83→//!     }
 84→//!
 85→//!     async fn create_tables(
 86→//!         &mut self,
 87→//!         run_id: Uuid,
 88→//!         datasets: HashMap<String, DatasetConfig>,
 89→//!     ) -> Result<CreateTablesResponse, String> {
 90→//!         let _ = datasets;
 91→//!         Ok(CreateTablesResponse { ok: true })
 92→//!     }
 93→//!
 94→//!     async fn teardown(&mut self, run_id: Uuid) -> Result<TeardownResponse, String> {
 95→//!         Ok(TeardownResponse { ok: true })
 96→//!     }
 97→//! }
 98→//!
 99→//! // Run the server on stdio
100→//! let mut server = Server::new(MyHandler);
101→//! server.run_stdio().await?;
102→//! # Ok(())
103→//! # }
104→//! ```
