264→/// Standard JSON-RPC 2.0 request envelope
265→#[derive(Debug, Clone, Serialize, Deserialize)]
266→pub struct JsonRpcRequest<T> {
267→    pub jsonrpc: String,
268→    pub id: serde_json::Value,
269→    pub method: String,
270→    pub params: T,
271→}
272→
273→impl<T> JsonRpcRequest<T> {
274→    /// Create a new JSON-RPC 2.0 request
275→    pub fn new(id: impl Into<serde_json::Value>, method: impl Into<String>, params: T) -> Self {
276→        Self {
277→            jsonrpc: "2.0".to_string(),
278→            id: id.into(),
279→            method: method.into(),
280→            params,
281→        }
282→    }
283→}
284→
285→/// Standard JSON-RPC 2.0 response envelope
286→#[derive(Debug, Clone, Serialize, Deserialize)]
287→pub struct JsonRpcResponse<T> {
288→    pub jsonrpc: String,
289→    pub id: serde_json::Value,
290→    #[serde(skip_serializing_if = "Option::is_none")]
291→    pub result: Option<T>,
292→    #[serde(skip_serializing_if = "Option::is_none")]
293→    pub error: Option<JsonRpcError>,
294→}
295→
296→impl<T> JsonRpcResponse<T> {
297→    /// Create a successful response
298→    pub fn success(id: impl Into<serde_json::Value>, result: T) -> Self {
299→        Self {
300→            jsonrpc: "2.0".to_string(),
301→            id: id.into(),
302→            result: Some(result),
303→            error: None,
304→        }
305→    }
306→
307→    /// Create an error response
308→    pub fn error(id: impl Into<serde_json::Value>, error: JsonRpcError) -> Self {
309→        Self {
310→            jsonrpc: "2.0".to_string(),
311→            id: id.into(),
312→            result: None,
313→            error: Some(error),
314→        }
315→    }
316→}
317→
318→/// JSON-RPC 2.0 error object
319→#[derive(Debug, Clone, Serialize, Deserialize)]
320→pub struct JsonRpcError {
321→    pub code: i32,
322→    pub message: String,
323→    #[serde(skip_serializing_if = "Option::is_none")]
324→    pub data: Option<serde_json::Value>,
325→}
326→
327→impl JsonRpcError {
328→    /// Create a new error
329→    pub fn new(code: i32, message: impl Into<String>) -> Self {
330→        Self {
331→            code,
332→            message: message.into(),
333→            data: None,
334→        }
335→    }
336→
337→    /// Create an error with additional data
338→    pub fn with_data(
339→        code: i32,
340→        message: impl Into<String>,
341→        data: impl Into<serde_json::Value>,
342→    ) -> Self {
343→        Self {
344→            code,
345→            message: message.into(),
346→            data: Some(data.into()),
347→        }
348→    }
349→}
