 17→//! Client implementations for system adapter JSON-RPC communication.
 18→
 19→use crate::{JsonRpcError, JsonRpcRequest, JsonRpcResponse, methods};
 20→use serde::{Serialize, de::DeserializeOwned};
 21→use std::collections::HashMap;
 22→use tokio::{
 23→    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
 24→    process::{Child, ChildStdin, ChildStdout, Command},
 25→};
 26→
 27→/// Result type for client operations
 28→pub type Result<T> = std::result::Result<T, ClientError>;
 29→
 30→/// Errors that can occur during client operations
 31→#[derive(Debug)]
 32→pub enum ClientError {
 33→    /// JSON-RPC error returned by the server
 34→    JsonRpc(JsonRpcError),
 35→    /// I/O error during communication
 36→    Io(std::io::Error),
 37→    /// JSON serialization/deserialization error
 38→    Json(serde_json::Error),
 39→    /// HTTP transport error
 40→    #[cfg(feature = "client")]
 41→    Http(reqwest::Error),
 42→    /// Invalid response format
 43→    InvalidResponse(String),
 44→    /// Transport-specific error
 45→    Transport(String),
 46→}
 47→
 48→impl std::fmt::Display for ClientError {
 49→    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
 50→        match self {
 51→            Self::JsonRpc(e) => write!(f, "JSON-RPC error: {}", e.message),
 52→            Self::Io(e) => write!(f, "I/O error: {e}"),
 53→            Self::Json(e) => write!(f, "JSON error: {e}"),
 54→            #[cfg(feature = "client")]
 55→            Self::Http(e) => write!(f, "HTTP error: {e}"),
 56→            Self::InvalidResponse(msg) => write!(f, "Invalid response: {msg}"),
 57→            Self::Transport(msg) => write!(f, "Transport error: {msg}"),
 58→        }
 59→    }
 60→}
 61→
 62→impl std::error::Error for ClientError {}
 63→
 64→impl From<std::io::Error> for ClientError {
 65→    fn from(e: std::io::Error) -> Self {
 66→        Self::Io(e)
 67→    }
 68→}
 69→
 70→impl From<serde_json::Error> for ClientError {
 71→    fn from(e: serde_json::Error) -> Self {
 72→        Self::Json(e)
 73→    }
 74→}
 75→
 76→#[cfg(feature = "client")]
 77→impl From<reqwest::Error> for ClientError {
 78→    fn from(e: reqwest::Error) -> Self {
 79→        Self::Http(e)
 80→    }
 81→}
 82→
 83→/// System adapter client for JSON-RPC communication
 84→pub enum Client {
 85→    /// Stdio transport - communicate via stdin/stdout with a child process
 86→    Stdio {
 87→        _child: Box<Child>,
 88→        stdin: ChildStdin,
 89→        stdout: BufReader<ChildStdout>,
 90→    },
 91→    /// HTTP transport - communicate via HTTP POST requests
 92→    #[cfg(feature = "client")]
 93→    Http {
 94→        client: reqwest::Client,
 95→        endpoint: String,
 96→    },
 97→}
 98→
 99→impl Client {
100→    /// Create a client using stdio transport by spawning a command
101→    pub fn stdio(
102→        command: impl AsRef<str>,
103→        args: Vec<String>,
104→        env: HashMap<String, String>,
105→    ) -> Result<Self> {
106→        let command_str = command.as_ref();
107→        let mut cmd = Command::new(command_str);
108→
109→        cmd.args(args);
110→        for (key, value) in env {
111→            cmd.env(key, value);
112→        }
113→
114→        cmd.stdin(std::process::Stdio::piped())
115→            .stdout(std::process::Stdio::piped())
116→            .stderr(std::process::Stdio::inherit());
117→
118→        let mut child = cmd.spawn().map_err(|e| {
119→            ClientError::Transport(format!(
120→                "Failed to start stdio command '{command_str}': {e}"
121→            ))
122→        })?;
123→
124→        let stdin = child
125→            .stdin
126→            .take()
127→            .ok_or_else(|| ClientError::Transport("Stdio child missing stdin".to_string()))?;
128→        let stdout = child
129→            .stdout
130→            .take()
131→            .ok_or_else(|| ClientError::Transport("Stdio child missing stdout".to_string()))?;
132→
133→        Ok(Self::Stdio {
134→            _child: Box::new(child),
135→            stdin,
136→            stdout: BufReader::new(stdout),
137→        })
138→    }
139→
140→    /// Create a client using HTTP transport
141→    #[cfg(feature = "client")]
142→    pub fn http(endpoint: impl Into<String>) -> Self {
143→        Self::Http {
144→            client: reqwest::Client::new(),
145→            endpoint: endpoint.into(),
146→        }
147→    }
148→
149→    /// Get the transport name
150→    pub fn transport_name(&self) -> &'static str {
151→        match self {
152→            Self::Stdio { .. } => "stdio",
153→            #[cfg(feature = "client")]
154→            Self::Http { .. } => "http",
155→        }
156→    }
157→
158→    /// Query available RPC methods from the server
159→    pub async fn rpc_methods(&mut self) -> Result<Vec<String>> {
160→        let request = JsonRpcRequest::new(1, methods::RPC_METHODS, serde_json::json!({}));
161→        let response: JsonRpcResponse<serde_json::Value> = self.call_typed(request).await?;
162→
163→        let methods = response
164→            .result
165→            .as_ref()
166→            .and_then(|v| v.get("methods"))
167→            .and_then(|v| v.as_array())
168→            .ok_or_else(|| {
169→                ClientError::InvalidResponse("Response missing result.methods array".to_string())
170→            })?
171→            .iter()
172→            .filter_map(|v| v.as_str().map(ToString::to_string))
173→            .collect();
174→
175→        Ok(methods)
176→    }
177→
178→    /// Setup a benchmark run
179→    pub async fn setup(
180→        &mut self,
181→        run_id: uuid::Uuid,
182→        metadata: std::collections::HashMap<String, serde_json::Value>,
183→    ) -> Result<crate::SetupResponse> {
184→        let request = crate::SetupRequest { run_id, metadata };
185→        let rpc_request = JsonRpcRequest::new(1, crate::methods::SETUP, request);
186→        let response = self.call_typed(rpc_request).await?;
187→        response
188→            .result
189→            .ok_or_else(|| ClientError::InvalidResponse("Missing result".to_string()))
190→    }
191→
192→    /// Create benchmark tables for a benchmark run
193→    pub async fn create_tables(
194→        &mut self,
195→        run_id: uuid::Uuid,
196→        datasets: std::collections::HashMap<String, crate::DatasetConfig>,
197→    ) -> Result<crate::CreateTablesResponse> {
198→        let request = crate::CreateTablesRequest { run_id, datasets };
199→        let rpc_request = JsonRpcRequest::new(1, crate::methods::CREATE_TABLES, request);
200→        let response = self.call_typed(rpc_request).await?;
201→        response
202→            .result
203→            .ok_or_else(|| ClientError::InvalidResponse("Missing result".to_string()))
204→    }
205→
206→    /// Teardown a benchmark run
207→    pub async fn teardown(&mut self, run_id: uuid::Uuid) -> Result<crate::TeardownResponse> {
208→        let request = crate::TeardownRequest { run_id };
209→        let rpc_request = JsonRpcRequest::new(1, crate::methods::TEARDOWN, request);
210→        let response = self.call_typed(rpc_request).await?;
211→        response
212→            .result
213→            .ok_or_else(|| ClientError::InvalidResponse("Missing result".to_string()))
214→    }
215→
216→    /// Collect current metrics from the system under test
217→    pub async fn metrics(&mut self, run_id: uuid::Uuid) -> Result<crate::MetricsResponse> {
218→        let request = crate::MetricsRequest { run_id };
219→        let rpc_request = JsonRpcRequest::new(1, crate::methods::METRICS, request);
220→        let response = self.call_typed(rpc_request).await?;
221→        response
222→            .result
223→            .ok_or_else(|| ClientError::InvalidResponse("Missing result".to_string()))
224→    }
225→
226→    /// Make a typed JSON-RPC call with request and response types
227→    async fn call_typed<Req: Serialize, Resp: DeserializeOwned>(
228→        &mut self,
229→        request: JsonRpcRequest<Req>,
230→    ) -> Result<JsonRpcResponse<Resp>> {
231→        let request_value = serde_json::to_value(request)?;
232→        let response_value = self.call_raw(request_value).await?;
233→        let response: JsonRpcResponse<Resp> = serde_json::from_value(response_value)?;
234→        Ok(response)
235→    }
236→
237→    /// Make a raw JSON-RPC call with serde_json::Value
238→    async fn call_raw(&mut self, request: serde_json::Value) -> Result<serde_json::Value> {
239→        match self {
240→            Self::Stdio {
241→                _child: _,
242→                stdin,
243→                stdout,
244→            } => {
245→                let payload = serde_json::to_string(&request)?;
246→                stdin.write_all(payload.as_bytes()).await?;
247→                stdin.write_all(b"\n").await?;
248→                stdin.flush().await?;
249→
250→                let mut line = String::new();
251→                let read = stdout.read_line(&mut line).await?;
252→                if read == 0 {
253→                    return Err(ClientError::Transport(
254→                        "Stdio process closed stdout before responding".to_string(),
255→                    ));
256→                }
257→
258→                let response: serde_json::Value = serde_json::from_str(line.trim_end())?;
259→                if let Some(error) = response.get("error") {
260→                    let error: JsonRpcError = serde_json::from_value(error.clone())?;
261→                    return Err(ClientError::JsonRpc(error));
262→                }
263→                Ok(response)
264→            }
265→            #[cfg(feature = "client")]
266→            Self::Http { client, endpoint } => {
267→                let response = client
268→                    .post(endpoint.as_str())
269→                    .json(&request)
270→                    .send()
271→                    .await
272→                    .map_err(|e| {
273→                        ClientError::Transport(format!("Failed to POST to {endpoint}: {e}"))
274→                    })?;
275→
276→                let status = response.status();
277→                let value: serde_json::Value = response.json().await.map_err(|e| {
278→                    ClientError::Transport(format!(
279→                        "Failed to parse response body (status {status}): {e}"
280→                    ))
281→                })?;
282→
283→                if let Some(error) = value.get("error") {
284→                    let error: JsonRpcError = serde_json::from_value(error.clone())?;
285→                    return Err(ClientError::JsonRpc(error));
286→                }
287→                Ok(value)
288→            }
289→        }
290→    }
291→}
