293→/// Builder for creating a `Client` with various configuration options
294→pub struct ClientBuilder {
295→    transport: TransportConfig,
296→}
297→
298→enum TransportConfig {
299→    Stdio {
300→        command: String,
301→        args: Vec<String>,
302→        env: HashMap<String, String>,
303→    },
304→    #[cfg(feature = "client")]
305→    Http { endpoint: String },
306→}
307→
308→impl ClientBuilder {
309→    /// Create a builder for stdio transport
310→    pub fn stdio(command: impl Into<String>) -> Self {
311→        Self {
312→            transport: TransportConfig::Stdio {
313→                command: command.into(),
314→                args: Vec::new(),
315→                env: HashMap::new(),
316→            },
317→        }
318→    }
319→
320→    /// Create a builder for HTTP transport
321→    #[cfg(feature = "client")]
322→    pub fn http(endpoint: impl Into<String>) -> Self {
323→        Self {
324→            transport: TransportConfig::Http {
325→                endpoint: endpoint.into(),
326→            },
327→        }
328→    }
329→
330→    /// Add command-line arguments (stdio only)
331→    pub fn with_args(mut self, args: Vec<String>) -> Self {
332→        if let TransportConfig::Stdio {
333→            args: ref mut a, ..
334→        } = self.transport
335→        {
336→            *a = args;
337→        }
338→        self
339→    }
340→
341→    /// Add environment variables (stdio only)
342→    pub fn with_env(mut self, env: HashMap<String, String>) -> Self {
343→        if let TransportConfig::Stdio { env: ref mut e, .. } = self.transport {
344→            *e = env;
345→        }
346→        self
347→    }
348→
349→    /// Build the client
350→    pub fn build(self) -> Result<Client> {
351→        match self.transport {
352→            TransportConfig::Stdio { command, args, env } => Client::stdio(command, args, env),
353→            #[cfg(feature = "client")]
354→            TransportConfig::Http { endpoint } => Ok(Client::http(endpoint)),
355→        }
356→    }
357→}
